gTE(){return"\u0906\u092a\u0915\u0947 \u092e\u0941\u0926\u094d\u0930\u093f\u0924 \u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c\u094b\u0902 \u092a\u0930 \u0939\u0930 \u091f\u0947\u092c\u0932/\u092c\u0949\u0915\u094d\u0938 \u092c\u0949\u0930\u094d\u0921\u0930 \u0915\u0947 \u0932\u093f\u090f \u092d\u0940 \u0909\u092a\u092f\u094b\u0917 \u0915\u093f\u092f\u093e \u091c\u093e\u0924\u093e \u0939\u0948 \u2014 \u092a\u094d\u0930\u093f\u0902\u091f \u0932\u0947\u0906\u0909\u091f \u0938\u094d\u0935\u092f\u0902 \u0915\u092d\u0940 \u0928\u0939\u0940\u0902 \u092c\u0926\u0932\u0924\u093e, \u0915\u0947\u0935\u0932 \u092f\u0939 \u090f\u0915 \u0930\u0902\u0917\u0964"},
gHt(){return"\u0926\u0938\u094d\u0924\u093e\u0935\u0947\u091c\u093c \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u0930\u0902\u0917"},
gTI(){return"\u0906\u0907\u091f\u092e \u0935\u093f\u0935\u0930\u0923, \u092a\u0924\u0947, \u0930\u093e\u0936\u093f\u092f\u093e\u0902 \u0914\u0930 \u0905\u0928\u094d\u092f \u092e\u0941\u0916\u094d\u092f \u092a\u093e\u0920"},
gTy(){return"\u0915\u0902\u092a\u0928\u0940 / \u0926\u0941\u0915\u093e\u0928 \u0915\u093e \u0928\u093e\u092e \u0906\u0935\u0936\u094d\u092f\u0915 \u0939\u0948\u0964"},
gTl(){return"\u0905\u092a\u0928\u0940 \u0915\u0902\u092a\u0928\u0940 \u0915\u093e \u0932\u094b\u0917\u094b \u091a\u0941\u0928\u0947\u0902"},
gT3(){return"\u0907\u0938 \u0930\u0902\u0917 \u0915\u093e \u0909\u092a\u092f\u094b\u0917 \u0915\u0930\u0947\u0902"},
gO3(){return"\u0915\u094d\u0932\u093e\u0909\u0921 \u091f\u0940\u092e \u2014 \u0938\u0926\u0938\u094d\u092f \u0926\u0947\u0916\u0947\u0902 \u092f\u093e \u0939\u091f\u093e\u090f\u0902"},
gO8(){return"\u0908\u092e\u0947\u0932 \u0926\u094d\u0935\u093e\u0930\u093e \u090f\u0915 \u0915\u0930\u094d\u092e\u091a\u093e\u0930\u0940 \u0915\u094b \u0906\u092e\u0902\u0924\u094d\u0930\u093f\u0924 \u0915\u0930\u0947\u0902"},
